  str_n29_11_name = "N7 - Verdad",
  str_n29_12_name = "N8 - Viaje de regreso",
  str_n29_13_name = "N9 - Batalla decisiva",
  str_n29_14_name = "N10 - Nueva Vida",
  str_n29_1_name_desc = "—",
  str_n29_2_name_desc = "Se ha producido un incendio en la ceremonia de inauguración. Te lanzas al fuego para rescatar a una niña atrapada. En este momento, Dark Slayer aparece frente a ti...",
  str_n29_3_name_desc = "—",
  str_n29_4_name_desc = "Kristen comienza a investigar la escena del incendio en el almacén del orfanato.",
  str_n29_5_name_desc = "Antes de la hora acordada para cambiar los colgantes, Hati tiene una conversación profunda contigo en el bosque.",
  str_n29_6_name_desc = "Este es un bosque cerca de Umbraton, un lugar donde viven los Eclipsites.",
  str_n29_7_name_desc = "—",
  str_n29_8_name_desc = "Hati está profundamente agitado. Los recuerdos de su infancia y de su madre pasan por su mente como una linterna giratoria.",
  str_n29_9_name_desc = "Kristen comienza a investigar el antiguo orfanato y se encuentra con Grimme, que está siendo atacado por Eclipsites.",
  str_n29_10_name_desc = "—",
  str_n29_11_name_desc = "te las arreglas para persuadir Kristen reconsiderar si Hati realmente es el pirómano.",
  str_n29_12_name_desc = "no será fácil para Hati, que es buscado por todo el pueblo, para entrar en Umbraton.",
  str_n29_13_name_desc = "Kristen, Hati, y Zenas se reúnen en el orfanato. Los rencores, tanto antiguos como nuevos, se resolverán aquí.",
  str_n29_14_name_desc = "Hati recupera el colgante que pertenecía a su madre. Necesita enfrentarse valientemente a su demonio interior antes de revelar el secreto del colgante.",
  str_n29_1_name_desc_long = "Por invitación de Bethel, vienes a Umbraton para asistir a la ceremonia de inauguración del orfanato de Umbraton. Kristen y Zenas del Lumo Hall of Justice están a cargo de la seguridad del evento. Te dicen que las cosas no han sido pacíficas en Umbraton recientemente y que un pirómano en serie llamado Dark Slayer ha estado vagando por todas partes en Umbraton.",
  str_n29_2_name_desc_long = "El almacén del orfanato está en llamas. Sientes que una niña pequeña está atrapada en el almacén, por lo que te precipitas dentro de las llamas para salvarla sin importar las consecuencias. Alguien te salva justo cuando la viga del edificio está a punto de caer después de haber sido quemada. Reconoces que esta persona es el Dark Slayer en los carteles de búsqueda.",
  str_n29_3_name_desc_long = "Te despiertas en Firefly Bar. El dueño, Grimme, te dice que el verdadero nombre de Dark Slayer es Hati y que ella no es una pirómana en serie. Después de escuchar toda la historia, decide ayudar Hati recuperar sus recuerdos perdidos...",
  str_n29_4_name_desc_long = "Tras investigar los incendios de los últimos dos meses, Kristen descubre que las víctimas de los incendios están todas relacionadas con el antiguo orfanato. Al mismo tiempo, Hati decide cambiarte por el colgante que lleva Zenas.",
  str_n29_5_name_desc_long = "El Sr. Hamell se niega a cooperar con la investigación de Kristen y Zenas consuela al frustrado Kristen. Por otro lado, usted y Hati son atacados por una gran cantidad de eclipses en el bosque cerca de Umbraton. En una situación crítica, Hati usa su poder, que siempre ha estado prohibido.",
  str_n29_6_name_desc_long = "—",
  str_n29_7_name_desc_long = "¿Es la hora acordada y la persona que ha venido es el Sr. Hamell? El Sr. Hamell es asesinado a la mitad de la conversación, y Kristen y Zenas aparecen para arrestar Hati. La máscara de Zenas se cae por accidente, revelando una cicatriz impactante en la mitad de su rostro en las sombras.",
  str_n29_8_name_desc_long = "Hati se agita profundamente en el momento en que Zenas muestra su rostro. Ella escapa de la escena contigo, pero está atrapada en los recuerdos de su infancia con su madre y no puede recuperar la compostura. Cuando Hati era pequeña, se sentía como un monstruo porque su madre le prohibía salir de casa y usar sus poderes. Su madre incluso la empujó a una chimenea.",
  str_n29_9_name_desc_long = "Kristen quiere saber qué sucedió en el antiguo orfanato, por lo que visita a dos huérfanos que una vez se quedaron allí y ahora viven en Lower Lumopolis. En el camino de regreso a Umbraton, Kristen salva a Grimme de un ataque de Eclipsite. Grimme invita Kristen para tomar una copa en el bar y le dice Kristen una historia de media verdad.",
  str_n29_10_name_desc_long = "Hati regresa al lugar donde una vez vivió con su madre. Se para en la chimenea para tratar de recordar lo que sucedió en ese entonces. La imagen de Kristen atropellar despierta los recuerdos de Hati. El día que la madre de Hati la empujó hacia la chimenea, un hombre irrumpió en la casa, asesinó brutalmente a su madre y se llevó el preciado colgante.",
  str_n29_11_name_desc_long = "Después de recuperar sus recuerdos, Hati alega que Zenas es el verdadero culpable que irrumpió en su casa, mató a su madre y tomó el colgante. La cicatriz en el rostro de Zenas es la evidencia. Kristen no está de acuerdo, señalando que Zenas consiguió esas cicatrices para salvarla. Las dos partes discuten acaloradamente, por lo que propones encontrar la evidencia crítica, el colgante.",
  str_n29_12_name_desc_long = "—",
  str_n29_13_name_desc_long = "Kristen encuentra a Zenas en el orfanato y le ruega que le entregue el colgante para demostrar su inocencia. Usted y Hati aparecer y explicar su razonamiento, pero Zenas piensa Kristen ha estado en connivencia con usted todo el tiempo. En una rabia avergonzada, Zenas toma Kristen como rehén y quiere culparte de todos los crímenes.",
  str_n29_14_name_desc_long = "Con tu ayuda, Hati vence a su demonio interior y fusiona el colgante de su madre con el suyo propio. Una foto de la familia de Hati se cae de un espacio oculto en el colgante, que es el tesoro más preciado de la madre de Hati. Con las bendiciones del sol y la niña, Hati da sus primeros pasos hacia un nuevo futuro.",
  str_n29_h1_name = "H1 - Asedio",
  str_n29_h2_name = "H2 - Serpiente larga",
  str_n29_h3_name = "H3 - Forma rota",
  str_n29_h4_name = "H4 - Aislamiento",
  str_n29_h1_name_desc = "La ruta de su avance es muy extraña. ¿Alguien podría estar dirigiéndolos? ¿O entrenar con una nueva táctica?",
  str_n29_h2_name_desc = "¿Por qué los enemigos están formando una larga fila? Sin embargo, no podemos permitir que su número aumente así... ¿Sería mejor atacar un lugar determinado para romper la línea?",
  str_n29_h3_name_desc = "La tierra está agrietada en el desierto accidentado y quebrado. ¿Cómo puedes derrotar a tus enemigos rápidamente si tienes problemas para acercarte a ellos?",
  str_n29_h4_name_desc = "El terreno dificulta el movimiento de nuestro lado. Naturalmente, el enemigo también se ve afectado. ¿Quizás podamos aprovechar esto?",
  str_n29_bh1_name = "EX1 - Sombra de ébano",
  str_n29_bh2_name = "EX2 - Plagas",
  str_n29_bh3_name = "EX3 - Guerra Civil",
  str_n29_bh1_sub_name_1 = "EX1-1 - Ebonshade: Garra de acero",
  str_n29_bh1_sub_name_2 = "EX1-2 - Ebonshade: Pelea",
  str_n29_bh2_sub_name_1 = "EX2-1 - Plaga: La reunión",
  str_n29_bh2_sub_name_2 = "EX2-2 - Plaga: Acuerdo roto",
  str_n29_bh3_sub_name_1 = "EX3-1 - Derrame de sangre: Perro solitario",
  str_n29_bh3_sub_name_2 = "EX3-2 - Derrame de sangre: La llama",
  str_n29_bh3_sub_name_3 = "EX3-3 - Derrame de sangre: Guerrilla",
  str_n29_tlxh_title = "Patrulla Semanal"
